const { loadApi } = require('./query-load-more-harness.js');

const output = path.join(fs.mkdtempSync(path.join(os.tmpdir(), 'rdf4j-explore-render-')), 'app.js');
const source = path.resolve(__dirname, '../../../main/frontend/classic/workbenchApp.ts');
