function flatten(value) {
    if (Array.isArray(value)) return value.map(flatten).join('');
    if (value && Array.isArray(value.strings)) return value.strings.reduce((out, part, i) =>
        out + part + (i < value.values.length ? flatten(value.values[i]) : ''), '');
    return value === null || value === undefined || typeof value === 'function' ? '' : String(value);
}
const runtime = { html(strings, ...values) { return { strings: Array.from(strings), values }; },
    render(template, mount) { mount.template = template; } };

test('section rendering presents overlapping roles, local pages, exact counts, and independent failures', () => {
    const sections = {};
    for (const key of ['outgoing', 'incoming', 'predicate', 'graph', 'types', 'superClasses', 'subClasses',
        'properties', 'superProperties', 'subProperties', 'domain', 'range', 'label', 'comment']) {
        sections[key] = { key, status: 'ready', countStatus: 'ready', count: '0', rows: [], totalRows: 0,
            start: 0, vars: ['value'], expanded: false };
    }
    const term = { kind: 'iri', value: 'urn:resource' };
    for (const key of ['outgoing', 'incoming', 'predicate', 'graph']) {
        Object.assign(sections[key], { vars: ['subject', 'predicate', 'object', 'context'],
            rows: [[term, term, term, term]], totalRows: 10000, count: '9007199254741000' });
    }
    Object.assign(sections.types, { rows: [[{ kind: 'iri', value: 'urn:type' }]], totalRows: 1, count: '1' });
    Object.assign(sections.range, { status: 'error', error: 'range failed', countStatus: 'error',
        countError: 'count failed' });
    const model = { viewId: 'explore', vars: [], rows: [], rowCount: 0, rowStore: {}, namespaceMap: {}, links: [],
        metadata: { resource: '<urn:resource>', 'explore-resource': '<urn:resource>' }, exploreSections: sections,
        exploreController: { page() {}, expand() {}, retry() {} } };
    const host = {};
    const outlet = { querySelector(selector) { return selector === '#explore-section-output' ? host : null; } };
    workbench.views.renderExploreSections(outlet, model, { basePath: '/workbench', repositoryId: 'r', workbench: {} }, runtime);
    const html = flatten(host.template);
    for (const key of ['outgoing', 'incoming', 'predicate', 'graph']) assert.match(html, new RegExp(`data-explore-role=${key}`));
    assert.match(html, /9007199254741000/);
    assert.match(html, /urn:type/);
    assert.match(html, /range failed/);
    assert.match(html, /count failed/);
    assert.match(html, /Load more/);
    assert.match(html, /Previous/);
    assert.match(html, /Next/);
    assert.doesNotMatch(html, />All</);
    assert.doesNotMatch(html, /Super Classes/, 'completed empty value sections stay out of the page');
});

test('an entirely empty explored resource has one clear empty result message', () => {
    const sections = {};
    for (const key of ['outgoing', 'incoming', 'predicate', 'graph', 'types', 'superClasses', 'subClasses',
        'properties', 'superProperties', 'subProperties', 'domain', 'range', 'label', 'comment']) {
        sections[key] = { key, status: 'ready', countStatus: 'ready', count: '0', rows: [], totalRows: 0,
            start: 0, vars: ['value'] };
    }
    const model = { viewId: 'explore', vars: [], rows: [], rowCount: 0, rowStore: {}, namespaceMap: {}, links: [],
        metadata: { resource: '<urn:r>', 'explore-resource': '<urn:r>' }, exploreSections: sections,
        exploreController: { page() {}, expand() {}, retry() {} } };
    const host = {};
    workbench.views.renderExploreSections({ querySelector() { return host; } }, model, { workbench: {} }, runtime);
    assert.match(flatten(host.template), /No results to display/);
});

test('Load more appears at the cache boundary only when a count may exceed it', () => {
    for (const [cached, status, count, expected] of [[9999, 'ready', '10001', false], [10000, 'ready', '10000', false],
        [10000, 'ready', '10001', true], [10000, 'ready', '9007199254740993', true],
        [10000, 'error', null, true], [10000, 'loading', null, true]]) {
        const section = { key: 'types', status: 'ready', countStatus: status, count, countError: 'unavailable',
            rows: [[{ kind: 'iri', value: 'urn:type' }]], totalRows: cached, start: 0, vars: ['value'] };
        const model = { viewId: 'explore', vars: [], rows: [], rowCount: 0, rowStore: {}, namespaceMap: {}, links: [],
            metadata: { resource: '<urn:r>', 'explore-resource': '<urn:r>' }, exploreSections: { types: section },
            exploreController: { page() {}, expand() {}, retry() {} } };
        const host = {};
        workbench.views.renderExploreSections({ querySelector() { return host; } }, model, { workbench: {} }, runtime);
        assert.equal(flatten(host.template).includes('Load more'), expected, `cached=${cached}, count=${count}`);
    }
});

test('metadata-only Explore keeps the requested resource text in its input', () => {
    const model = { viewId: 'explore', vars: [], rows: [], rowCount: 0, namespaceMap: {}, links: [],
        metadata: { 'explore-resource': '<urn:resolved>' },
        finalUrl: 'https://example.test/explore?resource=ex%3AC%2B%2B%3D1' };
    const html = flatten(workbench.views.pageTemplate(model, { workbench: {} }, runtime));
    assert.match(html, /value=ex:C\+\+=1/);
});

test('Clear and Remove show unverified blank graphs without making them reusable operands', () => {
    workbench.queryStream = loadApi().api;
    const blank = { kind: 'bnode', value: 'generated', scope: 'response-one' };
    const stored = { kind: 'bnode', value: 'stored', reference: true };
    const base = { vars: ['context', 'statements'], rows: [[blank, '2'], [stored, '3']], rowCount: 2,
        namespaceMap: {}, links: [], metadata: {} };
    for (const viewId of ['clear', 'remove']) {
        const html = flatten(workbench.views.pageTemplate({ ...base, viewId }, { workbench: {}, repositoryId: 'r' }, runtime));
        assert.match(html, /_:generated/, `${viewId} leaves the unverified graph visible`);
        assert.doesNotMatch(html, /value=<_\:generated>/, `${viewId} must not turn its label into a repository reference`);
        assert.match(html, /value=<_\:stored>/, `${viewId} keeps certified stored graph references usable`);
    }
});

test('classic graph counts use scoped typed identity instead of a blank-node display string', () => {
    const stream = loadApi().api;
    workbench.queryStream = stream;
    const pageContext = { workbench: {}, serverIdentity: 'server', basePath: '/workbench', repositoryId: 'r' };
    const repositoryScope = JSON.stringify(['server', '/workbench', 'r']);
    const listed = { kind: 'bnode', value: 'same', scope: 'list-response' };
    const other = { kind: 'bnode', value: 'same', scope: 'count-response' };
    const model = { viewId: 'contexts', vars: ['context'], rows: [[listed]], rowCount: 1, namespaceMap: {}, links: [],
        metadata: {}, browseCounts: { state: 'done', listed: 1,
            values: { [stream.termIdentity(other, repositoryScope)]: '123456789' } } };
    const first = flatten(workbench.views.pageTemplate(model, pageContext, runtime));
    assert.doesNotMatch(first, /123456789/, 'a response-local label is not the same graph in another response');
    model.browseCounts.values[stream.termIdentity(listed, repositoryScope)] = '42';
    const second = flatten(workbench.views.pageTemplate(model, pageContext, runtime));
    assert.match(second, />42<\/td>/);
    model.rows = [[{ ...listed, reference: true }]];
    model.browseCounts.values = { [stream.termIdentity({ ...other, reference: true }, repositoryScope)]: '43' };
    const certified = flatten(workbench.views.pageTemplate(model, pageContext, runtime));
    assert.match(certified, />43<\/td>/, 'certified repository identity survives a response change');
});
